function alphaLabel(index:number){let value=index+1,output='';while(value>0){const r=(value-1)%26;output=String.fromCharCode(65+r)+output;value=Math.floor((value-1)/26)}return output}
function stringValue(value:CellValue){return value===null||value===undefined?'':String(value)}
function parseNumber(value:CellValue):number|null{if(typeof value==='number'&&Number.isFinite(value))return value;if(typeof value!=='string')return null;let text=value.trim();if(!text)return null;const negative=/^\(.*\)$/.test(text);text=text.replace(/[,$%]/g,'').replace(/[()]/g,'').trim();const parsed=Number(text);return Number.isFinite(parsed)?(negative?-parsed:parsed):null}
function inferType(values:CellValue[]):ColumnType{const present=values.filter(v=>stringValue(v).trim()!=='').slice(0,200);if(!present.length)return'text';if(present.filter(v=>parseNumber(v)!==null).length/present.length>=.8)return'number';if(present.filter(v=>/^(true|false|yes|no|y|n|0|1)$/i.test(stringValue(v).trim())).length/present.length>=.9)return'boolean';const dates=present.filter(v=>{const t=stringValue(v).trim();return/[-/]|\b(?:jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)\b/i.test(t)&&Number.isFinite(Date.parse(t))}).length;if(dates/present.length>=.8)return'date';const unique=new Set(present.map(v=>stringValue(v).trim())).size;return unique<=Math.max(20,Math.ceil(present.length*.25))?'category':'text'}
function cleanHeader(value:CellValue,index:number,used:Set<string>){const base=stringValue(value).trim()||`Column ${alphaLabel(index)}`;let name=base,suffix=2;while(used.has(name.toLowerCase()))name=`${base} ${suffix++}`;used.add(name.toLowerCase());return name}
function formatNumber(value:number){if(!Number.isFinite(value))return'—';if(Math.abs(value)>=1_000_000)return new Intl.NumberFormat('en-US',{notation:'compact',maximumFractionDigits:1}).format(value);if(Math.abs(value)>=1_000)return new Intl.NumberFormat('en-US',{maximumFractionDigits:0}).format(value);return new Intl.NumberFormat('en-US',{maximumFractionDigits:2}).format(value)}
function escapeCsv(value:CellValue){const text=stringValue(value);return/[",\n\r]/.test(text)?`"${text.replace(/"/g,'""')}"`:text}
function downloadText(filename:string,content:string,mime='text/plain;charset=utf-8'){const blob=new Blob([content],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function aggregateValues(values:number[],aggregate:Aggregate){if(aggregate==='count')return values.length;if(!values.length)return 0;if(aggregate==='sum')return values.reduce((s,v)=>s+v,0);if(aggregate==='average')return values.reduce((s,v)=>s+v,0)/values.length;if(aggregate==='min')return Math.min(...values);return Math.max(...values)}
function formatValue(spec:VisualSpec,value:number){return `${spec.metadata.describe.numberPrepend}${formatNumber(value)}${spec.metadata.describe.numberAppend}`}
function colors(theme:StudioTheme){return theme.categorical.length?theme.categorical:DEFAULT_THEME.categorical}

function buildAggregation(spec:VisualSpec,dataRows:CellValue[][],columns:ColumnDef[]){const dimension=columns.find(c=>c.id===spec.dimension),measure=columns.find(c=>c.id===spec.measure),series=columns.find(c=>c.id===spec.series);if(!dimension)return{points:[] as AggregatedPoint[],seriesNames:[] as string[]};const bucket=new Map<string,Map<string,number[]>>();for(const row of dataRows){const category=stringValue(row[dimension.sourceIndex]).trim()||'(blank)',seriesName=series?stringValue(row[series.sourceIndex]).trim()||'(blank)':'Value',numeric=spec.aggregate==='count'?1:measure?parseNumber(row[measure.sourceIndex]):null;if(numeric===null)continue;if(!bucket.has(category))bucket.set(category,new Map());const bySeries=bucket.get(category)!;if(!bySeries.has(seriesName))bySeries.set(seriesName,[]);bySeries.get(seriesName)!.push(numeric)}const seriesNames=[...new Set([...bucket.values()].flatMap(m=>[...m.keys()]))].slice(0,10);let points=[...bucket.entries()].map(([category,bySeries])=>{const values:Record<string,number>={};for(const s of seriesNames)values[s]=aggregateValues(bySeries.get(s)||[],spec.aggregate);return{category,values,total:Object.values(values).reduce((a,b)=>a+b,0)}});if(['d3-bars','d3-dot-plot','d3-pies','d3-donuts','radial-process'].includes(spec.type))points.sort((a,b)=>b.total-a.total);return{points:points.slice(0,spec.topN),seriesNames}}
function aggregateSecond(spec:VisualSpec,dataRows:CellValue[][],columns:ColumnDef[]){const dimension=columns.find(c=>c.id===spec.dimension),measure=columns.find(c=>c.id===spec.measure2);if(!dimension||!measure)return new Map<string,number>();const bucket=new Map<string,number[]>();for(const row of dataRows){const key=stringValue(row[dimension.sourceIndex]).trim()||'(blank)',n=parseNumber(row[measure.sourceIndex]);if(n===null)continue;if(!bucket.has(key))bucket.set(key,[]);bucket.get(key)!.push(n)}return new Map([...bucket.entries()].map(([k,v])=>[k,aggregateValues(v,spec.aggregate)]))}

function SvgFrame({children,aria}:{children:React.ReactNode;aria:string}){return <svg className="dp-svg" viewBox="0 0 900 460" role="img" aria-label={aria}>{children}</svg>}
function EmptyVisual({message}:{message:string}){return <div className="dp-empty"><span>▦</span><strong>Choose fields to build this visual</strong><p>{message}</p></div>}
function opacityFor(spec:VisualSpec,category:string){const highlight=spec.metadata.annotate.highlightCategory.trim();return !highlight||highlight===category?1:.22}

function HorizontalVisual({spec,dataRows,columns,theme}:{spec:VisualSpec;dataRows:CellValue[][];columns:ColumnDef[];theme:StudioTheme}){const {points,seriesNames}=buildAggregation(spec,dataRows,columns);if(!points.length)return <EmptyVisual message="Choose a category field and measure."/>;const palette=colors(theme),second=aggregateSecond(spec,dataRows,columns),rowH=Math.min(44,330/Math.max(points.length,1));if(spec.type==='d3-bars-split'||spec.type==='d3-range-plot'||spec.type==='d3-arrow-plot'||spec.type==='d3-bars-bullet'){if(!spec.measure2)return <EmptyVisual message="This visual requires a second numeric measure."/>;const values=points.flatMap(p=>[p.total,second.get(p.category)||0]),min=Math.min(0,...values),max=Math.max(1,...values),range=max-min||1;return <SvgFrame aria={spec.metadata.describe.ariaDescription||spec.title}>{points.map((p,i)=>{const y=44+i*rowH,a=p.total,b=second.get(p.category)||0,xA=220+(a-min)/range*590,xB=220+(b-min)/range*590,alpha=opacityFor(spec,p.category);if(spec.type==='d3-bars-split'){const center=220+(0-min)/range*590;return <g key={p.category} opacity={alpha}><text x="18" y={y+10} className="dp-axis">{p.category.slice(0,25)}</text><rect x={Math.min(center,xA)} y={y-7} width={Math.abs(xA-center)} height="15" rx="4" fill={palette[0]}/><rect x={Math.min(center,xB)} y={y+9} width={Math.abs(xB-center)} height="15" rx="4" fill={palette[1]}/><line x1={center} x2={center} y1={y-11} y2={y+28} className="dp-zero"/></g>}if(spec.type==='d3-bars-bullet'){const base=220,w=(a-min)/range*590;return <g key={p.category} opacity={alpha}><text x="18" y={y+10} className="dp-axis">{p.category.slice(0,25)}</text><rect x={base} y={y-8} width={Math.max(2,w-base)} height="18" rx="4" fill={palette[0]}/><line x1={xB} x2={xB} y1={y-15} y2={y+17} stroke={palette[4]} strokeWidth="4"/></g>}return <g key={p.category} opacity={alpha}><text x="18" y={y+10} className="dp-axis">{p.category.slice(0,25)}</text><line x1={xA} x2={xB} y1={y} y2={y} stroke={palette[i%palette.length]} strokeWidth="3"/>{spec.type==='d3-arrow-plot'?<><circle cx={xA} cy={y} r="6" fill={palette[0]}/><polygon points={`${xB},${y} ${xB-12},${y-7} ${xB-12},${y+7}`} fill={palette[1]}/></>:<><circle cx={xA} cy={y} r="7" fill={palette[0]}/><circle cx={xB} cy={y} r="7" fill={palette[1]}/></>}</g>})}</SvgFrame>}
  const stacked=spec.type==='d3-bars-stacked';const max=Math.max(1,...points.map(p=>stacked?Object.values(p.values).reduce((a,b)=>a+b,0):p.total));return <SvgFrame aria={spec.metadata.describe.ariaDescription||spec.title}>{points.map((p,i)=>{const y=42+i*rowH,alpha=opacityFor(spec,p.category);if(stacked&&seriesNames.length>1){let cursor=220;return <g key={p.category} opacity={alpha}><text x="18" y={y+12} className="dp-axis">{p.category.slice(0,25)}</text>{seriesNames.map((s,si)=>{const w=(p.values[s]||0)/max*590,x=cursor;cursor+=w;return <rect key={s} x={x} y={y-7} width={w} height="19" fill={palette[si%palette.length]}/>} )}</g>}const w=p.total/max*590;return <g key={p.category} opacity={alpha}><text x="18" y={y+12} className="dp-axis">{p.category.slice(0,25)}</text><line x1="220" x2="810" y1={y+2} y2={y+2} className="dp-grid"/>{spec.type==='d3-dot-plot'?<><line x1="220" x2={220+w} y1={y+2} y2={y+2} stroke={palette[i%palette.length]} strokeWidth="2"/><circle cx={220+w} cy={y+2} r="8" fill={palette[i%palette.length]}/></>:<rect x="220" y={y-7} width={w} height="19" rx="4" fill={palette[i%palette.length]}/>}<text x={Math.min(860,232+w)} y={y+10} className="dp-value">{formatValue(spec,p.total)}</text></g>})}</SvgFrame>}

function ColumnVisual({spec,dataRows,columns,theme}:{spec:VisualSpec;dataRows:CellValue[][];columns:ColumnDef[];theme:StudioTheme}){const {points,seriesNames}=buildAggregation(spec,dataRows,columns);if(!points.length)return <EmptyVisual message="Choose a category field and measure."/>;const palette=colors(theme),left=76,top=30,width=780,height=338,group=width/Math.max(points.length,1),stacked=spec.type==='stacked-column-chart',series=seriesNames.length?seriesNames:['Value'],max=Math.max(1,...points.map(p=>stacked?Object.values(p.values).reduce((a,b)=>a+b,0):Math.max(...series.map(s=>p.values[s]||0))));return <SvgFrame aria={spec.metadata.describe.ariaDescription||spec.title}>{spec.metadata.visualize.showGrid&&[0,.25,.5,.75,1].map(t=><line key={t} x1={left} x2={left+width} y1={top+height-height*t} y2={top+height-height*t} className="dp-grid"/>)}{points.map((p,i)=>{const cx=left+i*group+group/2,alpha=opacityFor(spec,p.category);if(stacked&&series.length>1){let cursor=top+height;return <g key={p.category} opacity={alpha}>{series.map((s,si)=>{const h=(p.values[s]||0)/max*height,y=cursor-h;cursor=y;return <rect key={s} x={cx-Math.min(27,group*.33)} y={y} width={Math.min(54,group*.66)} height={h} fill={palette[si%palette.length]}/>})}<text x={cx} y={top+height+23} textAnchor="middle" className="dp-axis">{p.category.slice(0,11)}</text></g>}const bw=Math.max(4,Math.min(30,group*.72/Math.max(1,series.length)));return <g key={p.category} opacity={alpha}>{series.map((s,si)=>{const h=(p.values[s]||0)/max*height,x=cx-(series.length*bw)/2+si*bw;return <rect key={s} x={x} y={top+height-h} width={Math.max(3,bw-3)} height={h} rx="3" fill={palette[si%palette.length]}/>})}<text x={cx} y={top+height+23} textAnchor="middle" className="dp-axis">{p.category.slice(0,11)}</text></g>})}</SvgFrame>}

function LineAreaVisual({spec,dataRows,columns,theme}:{spec:VisualSpec;dataRows:CellValue[][];columns:ColumnDef[];theme:StudioTheme}){const {points,seriesNames}=buildAggregation(spec,dataRows,columns);if(!points.length)return <EmptyVisual message="Choose an ordered category/date field and measure."/>;const palette=colors(theme),left=78,top=30,width=772,height=338,max=Math.max(1,...points.flatMap(p=>seriesNames.map(s=>p.values[s]||0)));return <SvgFrame aria={spec.metadata.describe.ariaDescription||spec.title}>{spec.metadata.visualize.showGrid&&[0,.25,.5,.75,1].map(t=><line key={t} x1={left} x2={left+width} y1={top+height-height*t} y2={top+height-height*t} className="dp-grid"/>)}{seriesNames.map((s,si)=>{const coords=points.map((p,i)=>({x:left+(points.length===1?width/2:i*width/(points.length-1)),y:top+height-(p.values[s]||0)/max*height})),path=coords.map(c=>`${c.x},${c.y}`).join(' '),area=`${left},${top+height} ${path} ${left+width},${top+height}`;return <g key={s}>{spec.type==='d3-area'&&<polygon points={area} fill={palette[si%palette.length]} opacity=".16"/>}<polyline points={path} fill="none" stroke={palette[si%palette.length]} strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"/>{coords.map((c,i)=><circle key={i} cx={c.x} cy={c.y} r="4" fill={palette[si%palette.length]}/>)}</g>})}{points.map((p,i)=><text key={p.category} x={left+(points.length===1?width/2:i*width/(points.length-1))} y={top+height+24} textAnchor="middle" className="dp-axis">{p.category.slice(0,11)}</text>)}</SvgFrame>}

function PieVisual({spec,dataRows,columns,theme}:{spec:VisualSpec;dataRows:CellValue[][];columns:ColumnDef[];theme:StudioTheme}){const {points,seriesNames}=buildAggregation(spec,dataRows,columns);if(!points.length)return <EmptyVisual message="Choose a category field and measure."/>;const palette=colors(theme),multiple=spec.type==='d3-multiple-pies'||spec.type==='d3-multiple-donuts',donut=spec.type==='d3-donuts'||spec.type==='d3-multiple-donuts';if(multiple&&seriesNames.length>1){const smallSeries=seriesNames.slice(0,4);return <SvgFrame aria={spec.metadata.describe.ariaDescription||spec.title}>{smallSeries.map((series,si)=>{const cx=150+si*200,cy=205,r=72,c=2*Math.PI*r,total=points.reduce((sum,p)=>sum+Math.max(0,p.values[series]||0),0)||1;let offset=0;return <g key={series}>{points.map((p,i)=>{const f=Math.max(0,p.values[series]||0)/total,len=c*f,o=-c*offset;offset+=f;return <circle key={p.category} cx={cx} cy={cy} r={r} fill="none" stroke={palette[i%palette.length]} strokeWidth={donut?34:72} strokeDasharray={`${len} ${c-len}`} strokeDashoffset={o} transform={`rotate(-90 ${cx} ${cy})`}/>})}{donut&&<circle cx={cx} cy={cy} r="48" fill="var(--dp-bg,#fff)"/>}<text x={cx} y="315" textAnchor="middle" className="dp-axis-title">{series.slice(0,18)}</text></g>})}</SvgFrame>}
  const total=points.reduce((s,p)=>s+Math.max(0,p.total),0)||1,r=118,c=2*Math.PI*r;let offset=0;return <SvgFrame aria={spec.metadata.describe.ariaDescription||spec.title}><g transform="rotate(-90 290 225)">{points.map((p,i)=>{const f=Math.max(0,p.total)/total,len=c*f,o=-c*offset;offset+=f;return <circle key={p.category} cx="290" cy="225" r={r} fill="none" stroke={palette[i%palette.length]} strokeWidth={donut?58:118} strokeDasharray={`${len} ${c-len}`} strokeDashoffset={o}/>} )}</g>{donut&&<><circle cx="290" cy="225" r="80" fill="var(--dp-bg,#fff)"/><text x="290" y="220" textAnchor="middle" className="dp-total">{formatValue(spec,total)}</text></>}{spec.metadata.visualize.showLegend&&points.slice(0,8).map((p,i)=><g key={p.category} transform={`translate(510 ${85+i*40})`}><rect width="12" height="12" rx="3" fill={palette[i%palette.length]}/><text x="22" y="11" className="dp-axis">{p.category.slice(0,23)}</text><text x="320" y="11" textAnchor="end" className="dp-value">{formatValue(spec,p.total)}</text></g>)}</SvgFrame>}

function ScatterVisual({spec,dataRows,columns,theme}:{spec:VisualSpec;dataRows:CellValue[][];columns:ColumnDef[];theme:StudioTheme}){const xC=columns.find(c=>c.id===spec.dimension),yC=columns.find(c=>c.id===spec.measure),series=columns.find(c=>c.id===spec.series);if(!xC||!yC)return <EmptyVisual message="Choose numeric X and Y fields."/>;const dots=dataRows.flatMap((row,index)=>{const x=parseNumber(row[xC.sourceIndex]),y=parseNumber(row[yC.sourceIndex]);return x===null||y===null?[]:[{x,y,index,series:series?stringValue(row[series.sourceIndex]):''}]}).slice(0,1600);if(!dots.length)return <EmptyVisual message="No numeric pairs are available."/>;const minX=Math.min(...dots.map(d=>d.x)),maxX=Math.max(...dots.map(d=>d.x)),minY=Math.min(...dots.map(d=>d.y)),maxY=Math.max(...dots.map(d=>d.y)),rx=maxX-minX||1,ry=maxY-minY||1,palette=colors(theme),seriesNames=[...new Set(dots.map(d=>d.series))];return <SvgFrame aria={spec.metadata.describe.ariaDescription||spec.title}>{spec.metadata.visualize.showGrid&&[0,.25,.5,.75,1].map(t=><line key={t} x1="80" x2="850" y1={372-t*330} y2={372-t*330} className="dp-grid"/>)}{dots.map(d=><circle key={d.index} cx={80+(d.x-minX)/rx*770} cy={372-(d.y-minY)/ry*330} r="5" fill={palette[Math.max(0,seriesNames.indexOf(d.series))%palette.length]} opacity=".65"/>)}<text x="465" y="442" textAnchor="middle" className="dp-axis-title">{xC.name}</text></SvgFrame>}

function WaterfallVisual({spec,dataRows,columns,theme}:{spec:VisualSpec;dataRows:CellValue[][];columns:ColumnDef[];theme:StudioTheme}){const {points}=buildAggregation(spec,dataRows,columns);if(!points.length)return <EmptyVisual message="Choose a category and measure."/>;const palette=colors(theme);let running=0;const steps=points.map(p=>{const start=running;running+=p.total;return{...p,start,end:running}}),all=steps.flatMap(s=>[s.start,s.end,0]),min=Math.min(...all),max=Math.max(...all),range=max-min||1,left=72,top=32,w=780,h=340,group=w/Math.max(steps.length,1);return <SvgFrame aria={spec.metadata.describe.ariaDescription||spec.title}>{steps.map((s,i)=>{const y1=top+h-(s.start-min)/range*h,y2=top+h-(s.end-min)/range*h,y=Math.min(y1,y2),bh=Math.max(3,Math.abs(y2-y1)),cx=left+(i+.5)*group;return <g key={s.category}><line x1={i?left+(i-.5)*group:cx} x2={cx} y1={y1} y2={y1} className="dp-water"/><rect x={cx-Math.min(28,group*.32)} y={y} width={Math.min(56,group*.64)} height={bh} rx="3" fill={s.total>=0?palette[1]:palette[5%palette.length]}/><text x={cx} y={top+h+23} textAnchor="middle" className="dp-axis">{s.category.slice(0,10)}</text></g>})}</SvgFrame>}

